'use strict';
// Source-state audio lifecycle coverage only; this does not listen to sound.
const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
const c={require,console,__dirname};vm.createContext(c);vm.runInContext(fs.readFileSync(__dirname+'/audit-mechanical-audio.cjs','utf8').split('const results=[];')[0]+'\nglobalThis.fixture=make;',c);
const results=[];async function test(name,fn){try{await fn();results.push({name,ok:true});}catch(error){results.push({name,ok:false,error:String(error.stack)});}}
(async()=>{
await test('vending jam/recovery wait states have no active motor or scheduled pulse',async()=>{const t=c.fixture();t.api.attach('vending');t.api.update('vending',{phase:'drop',tokens:0});await t.enable();assert.equal(t.panel().dataset.audioLoop,'vend');for(const phase of ['jammed','recovering','recovered']){t.api.update('vending',{phase,tokens:0});t.contexts[0].tick(.1);assert.equal(t.panel().dataset.audioLoop,'none');assert.equal(+t.panel().dataset.audioVoices,0);const n=t.contexts[0].nodes.length;for(let i=0;i<100;i++)t.api.update('vending',{phase,tokens:0});assert.equal(t.contexts[0].nodes.length,n);}});
await test('continuing a recovered purchase resumes only the existing opted-in profile',async()=>{for(const enabled of [false,true]){const t=c.fixture();t.api.attach('vending');t.api.update('vending',{phase:'jammed',tokens:0});if(enabled)await t.enable();t.api.update('vending',{phase:'recovering',tokens:0});t.api.update('vending',{phase:'recovered',tokens:0});t.api.update('vending',{phase:'drop',tokens:0});assert.equal(t.panel().dataset.audioLoop,enabled?'vend':'none');assert.equal(t.contexts.length,enabled?1:0);}});
await test('leaving a jammed scene, resetting, hiding or muting cannot resurrect a loop',async()=>{for(const action of ['reset','pagehide','hidden','mute']){const t=c.fixture();t.api.attach('vending');t.api.update('vending',{phase:'drop',tokens:0});await t.enable();t.api.update('vending',{phase:'jammed',tokens:0});if(action==='reset')t.api.reset();if(action==='pagehide')t.event('pagehide');if(action==='hidden'){t.doc.hidden=true;t.event('doc:visibilitychange');}if(action==='mute')await t.click();t.api.update('vending',{phase:'jammed',tokens:0});t.contexts[0].tick(.1);assert.equal(+t.panel().dataset.audioVoices,0);assert.equal(t.panel().dataset.audioLoop,'none');}});
await test('camera diagram-like repeated same-state snapshots never create a second animation sound',async()=>{const t=c.fixture();t.api.attach('camera');t.api.update('camera',{phase:'ejecting'});await t.enable();const n=t.contexts[0].nodes.length;for(let i=0;i<100;i++)t.api.update('camera',{phase:'ejecting',eject:i/100});assert.equal(t.contexts[0].nodes.length,n);t.api.update('camera',{phase:'developing',eject:1});t.contexts[0].tick(.1);assert.equal(t.panel().dataset.audioLoop,'none');assert.equal(+t.panel().dataset.audioVoices,0);});
await test('camera lesson freeze silences the existing roller without granting consent or accumulating voices',async()=>{for(const enabled of [false,true]){const t=c.fixture();t.api.attach('camera');t.api.update('camera',{phase:'ejecting',lessonPaused:false});if(enabled)await t.enable();for(let i=0;i<20;i++){t.api.update('camera',{phase:'ejecting',lessonPaused:true});if(enabled)t.contexts[0].tick(.1);assert.equal(t.panel().dataset.audioLoop,'none');assert.equal(+t.panel().dataset.audioVoices,0);t.api.update('camera',{phase:'ejecting',lessonPaused:false});assert.equal(t.panel().dataset.audioLoop,enabled?'roller':'none');}t.api.dispose();if(enabled)t.contexts[0].tick(.1);assert.equal(t.contexts.length,enabled?1:0);}});
const report={passed:results.filter(r=>r.ok).length,total:results.length,limits:'Mocked WebAudio and DOM; no auditory-quality claim.',results};console.log(JSON.stringify(report,null,2));if(report.passed!==report.total)process.exitCode=1;
})();
